#!/bin/sh
# recipe 必须 Tab 开头：空格缩进触发 missing separator
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > Makefile << 'EOF'
CC := D:/mingw64/bin/gcc.exe
CFLAGS := -std=c11 -O2
app.exe: main.c util.c
    $(CC) $(CFLAGS) -o app.exe main.c util.c

clean:
    @rm -f app.exe
EOF

cat > main.c << 'EOF'
#include <stdio.h>
#include "util.h"

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

cat > util.c << 'EOF'
#include "util.h"

int add(int a, int b)
{
    return a + b;
}
EOF

cat > util.h << 'EOF'
int add(int a, int b);
EOF

cat -A Makefile | head -4      # ^I 表示 Tab；这里是空格，所以会失败
mingw32-make                   # 预期报 missing separator
